bool solve(vector<vector<char>>& b) {
    for (int r = 0; r < 9; ++r)
      for (int c = 0; c < 9; ++c)
        if (b[r][c] == '.') {
          for (char d = '1'; d <= '9'; ++d)
            if (valid(b, r, c, d)) {
              b[r][c] = d;
              if (solve(b)) return true;
              b[r][c] = '.';          // backtrack
            }
          return false;                // no digit fits
        }
    return true;                       // board full
}

def solve(board):                       # 9x9 list of chars, '.' = empty
    def valid(r, c, ch):
        for i in range(9):
            if board[r][i] == ch or board[i][c] == ch:
                return False
            if board[3*(r//3) + i//3][3*(c//3) + i%3] == ch:
                return False
        return True

    def bt():
        for r in range(9):
            for c in range(9):
                if board[r][c] == '.':
                    for ch in "123456789":
                        if valid(r, c, ch):
                            board[r][c] = ch
                            if bt():
                                return True
                            board[r][c] = '.'      # backtrack
                    return False                   # no digit fits
        return True                                # board full
    bt()
    return board

class Solution {
    bool valid(vector<vector<char>>& b, int r, int c, char d) {
        for (int i = 0; i < 9; i++) {
            if (b[r][i] == d || b[i][c] == d) return false;
            if (b[3*(r/3)+i/3][3*(c/3)+i%3] == d) return false;
        }
        return true;
    }
    bool solve(vector<vector<char>>& b) {
        for (int r = 0; r < 9; r++)
            for (int c = 0; c < 9; c++)
                if (b[r][c] == '.') {
                    for (char d = '1'; d <= '9'; d++)
                        if (valid(b, r, c, d)) { b[r][c] = d; if (solve(b)) return true; b[r][c] = '.'; }
                    return false;
                }
        return true;
    }
public:
    void solveSudoku(vector<vector<char>>& board) { solve(board); }
};

class Solution:
    def solveSudoku(self, board: list[list[str]]) -> None:
        def valid(r, c, d):
            for i in range(9):
                if board[r][i] == d or board[i][c] == d:
                    return False
                if board[3*(r//3)+i//3][3*(c//3)+i%3] == d:
                    return False
            return True
        def solve():
            for r in range(9):
                for c in range(9):
                    if board[r][c] == '.':
                        for d in '123456789':
                            if valid(r, c, d):
                                board[r][c] = d
                                if solve():
                                    return True
                                board[r][c] = '.'
                        return False
            return True
        solve()

class Solution {
public:
    bool isValidSudoku(vector<vector<char>>& b) {
        unordered_set<string> seen;
        for (int r = 0; r < 9; r++)
            for (int c = 0; c < 9; c++) {
                char d = b[r][c];
                if (d == '.') continue;
                if (!seen.insert("r" + to_string(r) + d).second) return false;
                if (!seen.insert("c" + to_string(c) + d).second) return false;
                if (!seen.insert("b" + to_string(r/3) + to_string(c/3) + d).second) return false;
            }
        return true;
    }
};

class Solution:
    def isValidSudoku(self, board: list[list[str]]) -> bool:
        seen = set()
        for r in range(9):
            for c in range(9):
                d = board[r][c]
                if d == '.':
                    continue
                keys = (("r", r, d), ("c", c, d), ("b", r//3, c//3, d))
                for k in keys:
                    if k in seen:
                        return False
                    seen.add(k)
        return True

class Solution {
    int n, count = 0; set<int> cols, d1, d2;
    void solve(int r) {
        if (r == n) { count++; return; }
        for (int c = 0; c < n; c++) {
            if (cols.count(c) || d1.count(r - c) || d2.count(r + c)) continue;
            cols.insert(c); d1.insert(r - c); d2.insert(r + c);
            solve(r + 1);
            cols.erase(c); d1.erase(r - c); d2.erase(r + c);
        }
    }
public:
    int totalNQueens(int N) { n = N; solve(0); return count; }
};

class Solution:
    def totalNQueens(self, n: int) -> int:
        self.count = 0
        cols, d1, d2 = set(), set(), set()
        def solve(r):
            if r == n:
                self.count += 1; return
            for c in range(n):
                if c in cols or (r - c) in d1 or (r + c) in d2:
                    continue
                cols.add(c); d1.add(r - c); d2.add(r + c)
                solve(r + 1)
                cols.discard(c); d1.discard(r - c); d2.discard(r + c)
        solve(0)
        return self.count

class Solution {
    struct Node { Node* ch[26] = {}; string word; };
    int R, C; vector<string> res;
    void dfs(vector<vector<char>>& b, int r, int c, Node* node) {
        if (r < 0 || c < 0 || r >= R || c >= C || b[r][c] == '#') return;
        char ch = b[r][c]; Node* nxt = node->ch[ch - 'a'];
        if (!nxt) return;
        if (!nxt->word.empty()) { res.push_back(nxt->word); nxt->word.clear(); }
        b[r][c] = '#';
        dfs(b, r+1, c, nxt); dfs(b, r-1, c, nxt); dfs(b, r, c+1, nxt); dfs(b, r, c-1, nxt);
        b[r][c] = ch;
    }
public:
    vector<string> findWords(vector<vector<char>>& board, vector<string>& words) {
        Node* root = new Node();
        for (auto& w : words) {
            Node* cur = root;
            for (char c : w) { if (!cur->ch[c-'a']) cur->ch[c-'a'] = new Node(); cur = cur->ch[c-'a']; }
            cur->word = w;
        }
        R = board.size(); C = board[0].size();
        for (int r = 0; r < R; r++) for (int c = 0; c < C; c++) dfs(board, r, c, root);
        return res;
    }
};

class Solution:
    def findWords(self, board: list[list[str]], words: list[str]) -> list[str]:
        trie = {}
        for w in words:
            node = trie
            for ch in w:
                node = node.setdefault(ch, {})
            node['$'] = w
        R, C, res = len(board), len(board[0]), []
        def dfs(r, c, node):
            ch = board[r][c]
            if ch not in node:
                return
            nxt = node[ch]
            if '$' in nxt:
                res.append(nxt['$']); del nxt['$']
            board[r][c] = '#'
            for nr, nc in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):
                if 0 <= nr < R and 0 <= nc < C and board[nr][nc] != '#':
                    dfs(nr, nc, nxt)
            board[r][c] = ch
        for r in range(R):
            for c in range(C):
                dfs(r, c, trie)
        return res

class Solution {
    bool ok(int v, vector<vector<int>>& g, vector<int>& color, int c) {
        for (int u = 0; u < (int)g.size(); u++) if (g[v][u] && color[u] == c) return false;
        return true;
    }
    bool solve(int v, vector<vector<int>>& g, int m, vector<int>& color) {
        if (v == (int)g.size()) return true;
        for (int c = 1; c <= m; c++)
            if (ok(v, g, color, c)) { color[v] = c; if (solve(v + 1, g, m, color)) return true; color[v] = 0; }
        return false;
    }
public:
    bool graphColoring(vector<vector<int>>& graph, int m) {
        vector<int> color(graph.size(), 0);
        return solve(0, graph, m, color);
    }
};

class Solution:
    def graphColoring(self, graph: list[list[int]], m: int) -> bool:
        n = len(graph)
        color = [0] * n
        def ok(v, c):
            return all(not (graph[v][u] and color[u] == c) for u in range(n))
        def solve(v):
            if v == n:
                return True
            for c in range(1, m + 1):
                if ok(v, c):
                    color[v] = c
                    if solve(v + 1):
                        return True
                    color[v] = 0
            return False
        return solve(0)
